def get_settings_row() -> Optional[Dict[str, Any]]:
    rows = fetch_rows(
        "device_settings",
        [
            "device_id",
            "cellular",
            "wifi",
            "location_service",
            "low_battery_mode",
            "latitude",
            "longitude",
        ],
    )
    return rows[0] if rows else None


def _to_sql(value: Any) -> Any:
    """Convert Python values to SQLite-storable ones (bool -> int)."""
    if isinstance(value, bool):
        return int(value)
    return value
